import subprocess
import time
import threading
def task_func(file_list):
    def run_file(file_path, results, index):
        try:
            process = subprocess.Popen(file_path, shell=True)
            process.wait()
            results[index] = process.returncode
        except Exception:
            results[index] = -1

    results = [-1] * len(file_list)
    threads = []

    for i, file_path in enumerate(file_list):
        thread = threading.Thread(target=run_file, args=(file_path, results, i))
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

    return results

