import time
def task_func(script_path, wait=True, *args):
    if not os.path.exists(script_path):
        raise ValueError("Script does not exist")
    try:
        process = subprocess.Popen([sys.executable, script_path, *args], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if wait:
            stdout, stderr = process.communicate()
            if process.returncode != 0:
                raise subprocess.CalledProcessError(process.returncode, script_path, output=stdout, stderr=stderr)
            return process.returncode
        else:
            return None
    except Exception as e:
        raise e

